  --ink: #07130e;
  --ink-2: #0c2018;
  --bone: #f4edd8;
  --muted: #a9b8a9;
  --moss: #78f0b4;
  --moss-dark: #17684f;
  --ember: #ffb35f;
  --ember-dark: #a44828;
  --danger: #ff6b57;
