/* Dino Duo — shared core, world, audio and input.
   Tiny by design: no images, no libraries, no network requests. */
(() => {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const W = 1280, H = 820;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
  const lerp = (a, b, t) => a + (b - a) * t;
  const rand = (a, b) => a + Math.random() * (b - a);
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const fmt = n => Math.floor(n).toLocaleString('en-US');

  function mulberry32(seed) {
    return function () {
      seed |= 0; seed = seed + 0x6D2B79F5 | 0;
      let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  function angleDelta(a, b) {
    let d = (b - a + Math.PI) % TAU;
    if (d < 0) d += TAU;
    return d - Math.PI;
  }
  function norm(x, y) {
    const d = Math.hypot(x, y) || 1;
    return { x: x / d, y: y / d };
  }

  const $ = id => document.getElementById(id);
  const ui = {
    hud: $('hud'), menu: $('menu'), pause: $('pauseMenu'), gameover: $('gameOver'),
    start: $('startBtn'), resume: $('resumeBtn'), quit: $('quitBtn'), again: $('playAgainBtn'), title: $('titleBtn'),
    sound: $('soundBtn'), pauseBtn: $('pauseBtn'),
    cards: [$('card0'), $('card1')], names: [$('name0'), $('name1')], levels: [$('level0'), $('level1')],
    hp: [$('hp0'), $('hp1')], hpText: [$('hpText0'), $('hpText1')], xp: [$('xp0'), $('xp1')],
    dash: [$('dash0'), $('dash1')], wave: $('waveLabel'), waveSub: $('waveSub'),
    score: $('scoreLabel'), boss: $('bossWrap'), bossBar: $('bossBar'),
    banner: $('banner'), bannerKick: $('bannerKicker'), bannerTitle: $('bannerTitle'), bannerSmall: $('bannerSmall'),
    toast: $('toastStack'), hint: $('hintBar'),
    best: $('bestScore'), resultWave: $('resultWave'), resultScore: $('resultScore'),
    resultLevels: [$('resultLevel0'), $('resultLevel1')], overCopy: $('overCopy'),
    touch: $('touchControls'), sticks: [$('stick0'), $('stick1')],
    dashButtons: Array.from(document.querySelectorAll('.dash-btn'))
  };

  const PLAYER_DEFS = [
    { name: 'MOSS', main: '#78f0b4', mid: '#21a97a', dark: '#0d5943', light: '#d7ffe8', glow: '120,240,180' },
    { name: 'EMBER', main: '#ffb35f', mid: '#d86d37', dark: '#77361d', light: '#ffe3bd', glow: '255,179,95' }
  ];
  const BOONS = [
    { id: 'rapid', name: 'Quick Draw', icon: '»', note: 'Fire rate up' },
    { id: 'power', name: 'Heavy Dart', icon: '◆', note: '+4 damage' },
    { id: 'vitality', name: 'Thick Hide', icon: '♥', note: '+20 max HP' },
    { id: 'fleet', name: 'Fleet Feet', icon: '≈', note: '+7% move speed' },
    { id: 'magnet', name: 'Amber Magnet', icon: '◎', note: 'Wider pickup range' },
    { id: 'regen', name: 'Second Wind', icon: '✚', note: 'Slow healing' }
  ];

  const baseState = () => ({
    mode: 'menu', time: 0, paused: false, score: 0, best: Number(localStorage.getItem('dinoduo.best') || 0),
    wave: 0, enemies: [], players: [], bullets: [], particles: [], pickups: [], texts: [], rings: [],
    spawnQueue: [], spawnTimer: 0, intermission: false, interTimer: 0,
    shake: 0, hurtFlash: 0, levelFlash: 0, gameOverDelay: 0, introTimer: 0,
    camera: { x: W / 2, y: H / 2, zoom: 1 }, dino: null, kills: 0
  });
  const state = baseState();

  /* ---------------- Audio ---------------- */
  const audio = {
    ac: null, master: null, muted: localStorage.getItem('dinoduo.muted') === '1',
    last: Object.create(null),
    init() {
      if (this.ac) { if (this.ac.state === 'suspended') this.ac.resume(); return; }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ac = new AC();
      this.master = this.ac.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      this.master.connect(this.ac.destination);
    },
    setMuted(v) {
      this.muted = v;
      localStorage.setItem('dinoduo.muted', v ? '1' : '0');
      document.body.classList.toggle('is-muted', v);
      if (this.master) this.master.gain.setTargetAtTime(v ? 0 : 0.55, this.ac.currentTime, 0.02);
    },
    tone(freq, endFreq, dur, type, vol, when = 0) {
      if (!this.ac || this.muted) return;
      const t = this.ac.currentTime + when;
      const o = this.ac.createOscillator();
      const g = this.ac.createGain();
      o.type = type;
      o.frequency.setValueAtTime(Math.max(30, freq), t);
      o.frequency.exponentialRampToValueAtTime(Math.max(30, endFreq), t + dur);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + dur + 0.02);
    },
    noise(dur, vol, freq, when = 0, q = 1) {
      if (!this.ac || this.muted) return;
      const t = this.ac.currentTime + when;
      const len = Math.floor(this.ac.sampleRate * dur);
      const buffer = this.ac.createBuffer(1, len, this.ac.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
      const src = this.ac.createBufferSource(); src.buffer = buffer;
      const filter = this.ac.createBiquadFilter(); filter.type = 'bandpass'; filter.frequency.value = freq; filter.Q.value = q;
      const g = this.ac.createGain(); g.gain.value = vol;
      src.connect(filter); filter.connect(g); g.connect(this.master);
      src.start(t);
    },
    play(name) {
      if (!this.ac || this.muted) return;
      const now = performance.now();
      if (this.last[name] && now - this.last[name] < 35) return;
      this.last[name] = now;
      if (name === 'shoot') this.tone(780, 310, 0.055, 'sine', 0.026);
      else if (name === 'hit') { this.tone(180, 92, 0.06, 'triangle', 0.045); this.noise(0.04, 0.022, 900); }
      else if (name === 'kill') { this.noise(0.13, 0.05, 420, 0, 0.7); this.tone(110, 55, 0.12, 'sine', 0.04); }
      else if (name === 'hurt') { this.tone(105, 48, 0.22, 'sawtooth', 0.055); this.noise(0.12, 0.04, 240, 0, 0.7); }
      else if (name === 'dash') { this.noise(0.13, 0.035, 1400, 0, 1.4); this.tone(300, 640, 0.09, 'sine', 0.014); }
      else if (name === 'pickup') this.tone(880, 1320, 0.07, 'sine', 0.023);
      else if (name === 'level') [523, 659, 784, 1046].forEach((f, i) => this.tone(f, f * 1.01, 0.22, 'triangle', 0.035, i * 0.075));
      else if (name === 'revive') [392, 523, 659].forEach((f, i) => this.tone(f, f, 0.24, 'sine', 0.03, i * 0.08));
      else if (name === 'roar') { this.tone(78, 38, 0.55, 'sawtooth', 0.07); this.noise(0.5, 0.045, 150, 0, 0.7); }
      else if (name === 'click') this.tone(520, 700, 0.06, 'sine', 0.025);
      else if (name === 'wave') [330, 440, 554].forEach((f, i) => this.tone(f, f, 0.3, 'triangle', 0.025, i * 0.09));
      else if (name === 'gameover') [220, 174, 130].forEach((f, i) => this.tone(f, f * 0.96, 0.55, 'sawtooth', 0.035, i * 0.16));
    }
  };
  audio.setMuted(audio.muted);

  /* ---------------- World ---------------- */
  const world = { trees: [], terrain: null, leafTimer: 0, ambient: [] };

  function buildTerrain() {
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    const g = c.getContext('2d');
    const rng = mulberry32(0x51d09a);

    g.fillStyle = '#102a1b';
    g.fillRect(0, 0, W, H);

    const base = g.createRadialGradient(W * 0.46, H * 0.36, 40, W * 0.5, H * 0.5, W * 0.8);
    base.addColorStop(0, '#2b5c34');
    base.addColorStop(0.38, '#214a2c');
    base.addColorStop(0.75, '#163722');
    base.addColorStop(1, '#0b2418');
    g.fillStyle = base; g.fillRect(0, 0, W, H);

    // Broad sunlit patches.
    for (let i = 0; i < 16; i++) {
      const x = rng() * W, y = rng() * H, r = 90 + rng() * 260;
      const rg = g.createRadialGradient(x, y, 0, x, y, r);
      const light = rng() > 0.46;
      rg.addColorStop(0, light ? 'rgba(133, 176, 91, .10)' : 'rgba(4, 24, 14, .15)');
      rg.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = rg; g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
    }

    // Winding game trail.
    g.save();
    g.lineCap = 'round'; g.lineJoin = 'round';
    const trail = new Path2D();
    trail.moveTo(638, 840);
    trail.bezierCurveTo(610, 720, 650, 640, 628, 548);
    trail.bezierCurveTo(600, 455, 455, 400, 410, 300);
    trail.bezierCurveTo(380, 232, 420, 150, 382, 60);
    g.strokeStyle = 'rgba(22, 17, 9, .2)'; g.lineWidth = 96; g.stroke(trail);
    g.strokeStyle = 'rgba(94, 77, 42, .22)'; g.lineWidth = 73; g.stroke(trail);
    g.strokeStyle = 'rgba(137, 112, 66, .12)'; g.lineWidth = 52; g.stroke(trail);
    g.restore();

    // Pond, with a stony lip.
    g.save();
    g.translate(1044, 208);
    const pond = new Path2D();
    pond.ellipse(0, 0, 133, 92, -0.18, 0, TAU);
    g.fillStyle = 'rgba(24, 21, 13, .35)';
    g.beginPath(); g.ellipse(4, 8, 145, 101, -0.18, 0, TAU); g.fill();
    g.fillStyle = '#143c39'; g.fill(pond);
    const water = g.createRadialGradient(-24, -26, 6, 0, 0, 128);
    water.addColorStop(0, 'rgba(108, 190, 159, .38)');
    water.addColorStop(0.45, 'rgba(34, 103, 89, .28)');
    water.addColorStop(1, 'rgba(5, 35, 31, .1)');
    g.fillStyle = water; g.fill(pond);
    g.strokeStyle = 'rgba(176, 205, 141, .17)'; g.lineWidth = 2; g.stroke(pond);
    for (let i = 0; i < 8; i++) {
      g.strokeStyle = `rgba(195, 239, 207, ${0.05 + rng() * 0.08})`;
      g.lineWidth = 1.4;
      g.beginPath(); g.ellipse(-40 + rng() * 80, -34 + rng() * 70, 12 + rng() * 40, 2 + rng() * 4, 0, 0, TAU); g.stroke();
    }
    g.restore();

    // Mossy stones.
    for (let i = 0; i < 34; i++) {
      const x = 40 + rng() * (W - 80), y = 40 + rng() * (H - 80);
      if (Math.hypot(x - 1044, y - 208) < 160) continue;
      const r = 3 + rng() * 11;
      g.fillStyle = 'rgba(6, 17, 11, .28)';
      g.beginPath(); g.ellipse(x + 3, y + 3, r * 1.15, r * 0.7, 0, 0, TAU); g.fill();
      g.fillStyle = `rgba(${86 + rng() * 30}, ${96 + rng() * 25}, ${72 + rng() * 20}, .65)`;
      g.beginPath(); g.ellipse(x, y, r, r * 0.72, rng(), 0, TAU); g.fill();
      g.fillStyle = 'rgba(132, 173, 111, .25)';
      g.beginPath(); g.ellipse(x - r * 0.2, y - r * 0.2, r * 0.62, r * 0.3, 0, 0, TAU); g.fill();
    }

    // Grass blades and tiny flowers.
    for (let i = 0; i < 1050; i++) {
      const x = 20 + rng() * (W - 40), y = 25 + rng() * (H - 45);
      const len = 2 + rng() * 7;
      g.strokeStyle = `rgba(${83 + rng() * 55}, ${125 + rng() * 55}, ${67 + rng() * 34}, ${0.16 + rng() * 0.26})`;
      g.lineWidth = 0.8 + rng() * 0.8;
      g.beginPath(); g.moveTo(x, y); g.quadraticCurveTo(x + (rng() - .5) * 4, y - len * .7, x + (rng() - .5) * 7, y - len); g.stroke();
    }
    for (let i = 0; i < 95; i++) {
      const x = 30 + rng() * (W - 60), y = 30 + rng() * (H - 60);
      const c1 = rng() > .5 ? 'rgba(246, 218, 139, .55)' : 'rgba(233, 145, 129, .38)';
      g.fillStyle = c1;
      g.beginPath(); g.arc(x, y, 1.2 + rng() * 1.3, 0, TAU); g.fill();
    }

    // Dark edges and a ring of undergrowth.
    const edge = g.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.36, W / 2, H / 2, Math.max(W, H) * 0.7);
    edge.addColorStop(0, 'rgba(0,0,0,0)');
    edge.addColorStop(1, 'rgba(2, 12, 8, .55)');
    g.fillStyle = edge; g.fillRect(0, 0, W, H);

    // Soft shafts of late-afternoon light.
    g.save();
    g.globalCompositeOperation = 'screen';
    for (let i = 0; i < 5; i++) {
      const x = 120 + i * 250 + rng() * 90;
      const grad = g.createLinearGradient(x, 0, x - 170, H);
      grad.addColorStop(0, 'rgba(255, 220, 137, .055)');
      grad.addColorStop(1, 'rgba(255, 220, 137, 0)');
      g.fillStyle = grad;
      g.beginPath(); g.moveTo(x, 0); g.lineTo(x + 130, 0); g.lineTo(x - 170, H); g.lineTo(x - 330, H); g.closePath(); g.fill();
    }
    g.restore();

    world.terrain = c;
  }

  function buildTrees() {
    const rng = mulberry32(0xbadc0de);
    const trees = [];
    const avoid = [{ x: 585, y: 638, r: 160 }, { x: 735, y: 638, r: 160 }, { x: 640, y: 790, r: 140 }];
    function canPlace(x, y) {
      if (x < 62 || x > W - 62 || y < 62 || y > H - 52) return false;
      if (Math.hypot(x - 1044, y - 208) < 155) return false;
      for (const a of avoid) if (Math.hypot(x - a.x, y - a.y) < a.r) return false;
      for (const t of trees) if (Math.hypot(x - t.x, y - t.y) < 102) return false;
      return true;
    }
    const palette = ['broad', 'broad', 'palm', 'broad', 'fern', 'palm'];
    const fixed = [
      [126, 120, 1.12, 0], [240, 88, .9, 2], [88, 288, 1.03, 1], [152, 470, .86, 3],
      [56, 655, 1.1, 0], [288, 730, .82, 2], [410, 112, .95, 3], [512, 70, .83, 1],
      [742, 108, 1.03, 0], [855, 72, .8, 2], [1182, 128, 1.12, 3], [1214, 330, .9, 1],
      [1140, 518, 1.04, 0], [1190, 684, .86, 2], [1046, 744, 1.05, 3], [896, 750, .82, 1],
      [560, 764, .78, 2], [408, 468, .86, 0], [870, 468, .9, 3], [758, 328, .72, 1],
      [252, 356, .78, 2], [960, 338, .84, 0]
    ];
    fixed.forEach(([x, y, s, v]) => trees.push({ x, y, scale: s, variant: palette[v], phase: rng() * TAU, r: 8.5 * s }));
    for (let i = 0; i < 34; i++) {
      const x = 72 + rng() * (W - 144), y = 70 + rng() * (H - 135);
      if (!canPlace(x, y)) continue;
      trees.push({
        x, y, scale: .66 + rng() * .5, variant: palette[Math.floor(rng() * palette.length)],
        phase: rng() * TAU, r: 8.5 * (.66 + rng() * .2)
      });
      if (trees.length >= 31) break;
    }
    world.trees = trees.sort((a, b) => a.y - b.y);
  }

  function initAmbient() {
    const rng = mulberry32(0x1eaf);
    world.ambient = [];
    for (let i = 0; i < 24; i++) {
      world.ambient.push({
        type: 'firefly', x: 70 + rng() * (W - 140), y: 80 + rng() * (H - 160),
        phase: rng() * TAU, speed: .2 + rng() * .5, r: 1 + rng() * 1.4
      });
    }
    for (let i = 0; i < 9; i++) {
      world.ambient.push({
        type: 'leaf', x: rng() * W, y: rng() * H, vx: 5 + rng() * 12, vy: 7 + rng() * 14,
        rot: rng() * TAU, spin: (rng() - .5) * 2, size: 2 + rng() * 2.5, hue: rng() > .5 ? '#9bae58' : '#c39a50'
      });
    }
  }

  /* ---------------- Input ---------------- */
  const input = {
    keys: new Set(), pressed: new Set(), touch: [{ x: 0, y: 0 }, { x: 0, y: 0 }],
    dash: [false, false],
    down(code) { return this.keys.has(code); }
  };

  function setupTouch() {
    ui.sticks.forEach((stick, index) => {
      let active = null, rect = null;
      const knob = stick.querySelector('.joystick-knob');
      const move = (e) => {
        if (e.pointerId !== active || !rect) return;
        let dx = e.clientX - (rect.left + rect.width / 2);
        let dy = e.clientY - (rect.top + rect.height / 2);
        const limit = rect.width * 0.31;
        const len = Math.hypot(dx, dy);
        if (len > limit) { dx = dx / len * limit; dy = dy / len * limit; }
        input.touch[index].x = dx / limit;
        input.touch[index].y = dy / limit;
        knob.style.transform = `translate(${dx}px, ${dy}px)`;
      };
      stick.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        active = e.pointerId; rect = stick.getBoundingClientRect();
        stick.setPointerCapture?.(e.pointerId);
        move(e);
      });
      stick.addEventListener('pointermove', move);
      const end = (e) => {
        if (e.pointerId !== active) return;
        active = null; rect = null;
        input.touch[index].x = 0; input.touch[index].y = 0;
        knob.style.transform = '';
      };
      stick.addEventListener('pointerup', end);
      stick.addEventListener('pointercancel', end);
      stick.addEventListener('lostpointercapture', end);
    });
    ui.dashButtons.forEach((button) => {
      const index = Number(button.dataset.player);
      button.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        audio.init();
        input.dash[index] = true;
        button.classList.add('pressed');
      });
      button.addEventListener('pointerup', () => button.classList.remove('pressed'));
      button.addEventListener('pointercancel', () => button.classList.remove('pressed'));
    });
  }

  function updateAmbient(dt) {
    world.leafTimer -= dt;
    if (world.leafTimer <= 0) {
      world.leafTimer = .7 + Math.random() * .9;
      const t = world.trees[Math.floor(Math.random() * world.trees.length)];
      world.ambient.push({
        type: 'leaf', x: t.x + (Math.random() - .5) * 60, y: t.y - 38 + (Math.random() - .5) * 20,
        vx: 7 + Math.random() * 9, vy: 10 + Math.random() * 12, rot: Math.random() * TAU,
        spin: (Math.random() - .5) * 2.5, size: 2 + Math.random() * 2.3,
        hue: Math.random() > .5 ? '#9bae58' : '#c39a50', life: 12
      });
    }
    for (const a of world.ambient) {
      if (a.type === 'leaf') {
        a.x += (a.vx + Math.sin(state.time + a.rot) * 7) * dt;
        a.y += a.vy * dt;
        a.rot += a.spin * dt;
        if (a.life != null) a.life -= dt;
        if (a.y > H + 20 || a.life < 0) { a.y = -20; a.x = 60 + Math.random() * (W - 120); if (a.life != null) a.life = 12; }
      }
    }
    world.ambient = world.ambient.filter(a => a.type !== 'leaf' || a.life == null || a.life > 0 || true);
    while (world.ambient.filter(a => a.type === 'leaf').length > 22) {
      const idx = world.ambient.findIndex(a => a.type === 'leaf');
      if (idx < 0) break;
      world.ambient.splice(idx, 1);
    }
  }

  window.DD = {
    canvas, ctx, W, H, TAU, clamp, lerp, rand, dist, fmt, mulberry32, angleDelta, norm,
    ui, PLAYER_DEFS, BOONS, state, audio, world, input,
    PLAY: { l: 54, r: W - 54, t: 58, b: H - 50 },
    view: { w: 0, h: 0, dpr: 1 },
    buildWorld() { buildTerrain(); buildTrees(); initAmbient(); },
    updateAmbient, setupTouch
  };
})();

/* Dino Duo — simulation: waves, combat, leveling and co-op revives. */
(() => {
  'use strict';
  const D = window.DD;
  const { state, ui, input, audio, world } = D;
  const { clamp, lerp, rand, dist, fmt, TAU, angleDelta, norm } = D;
  const PLAY = D.PLAY;

  const DINO = {
    raptor: { hp: 28, speed: 103, radius: 17, damage: 9, xp: 9, score: 60, name: 'RAPTOR' },
    ptero: { hp: 22, speed: 151, radius: 13, damage: 8, xp: 11, score: 80, name: 'PTERO' },
    stego: { hp: 105, speed: 59, radius: 28, damage: 16, xp: 23, score: 150, name: 'STEGO' },
    rex: { hp: 470, speed: 48, radius: 44, damage: 28, xp: 85, score: 900, name: 'TITAN', boss: true }
  };

  function createPlayer(index, x, y) {
    const def = D.PLAYER_DEFS[index];
    return {
      index, name: def.name, def, x, y, radius: 14,
      hp: 100, maxHp: 100, level: 1, xp: 0, xpNext: 30,
      speed: 174, damage: 10, fireDelay: 0.58, fireCd: 0.28,
      bulletSpeed: 545, multiShot: 1, pierce: 0, pickupRadius: 132,
      angle: -Math.PI / 2, aim: -Math.PI / 2, fireAngle: -Math.PI / 2,
      moveX: 0, moveY: 0, moving: false, walk: 0,
      dashCd: 0, dashCdMax: 2.35, dashTime: 0, dashVX: 0, dashVY: 0,
      invuln: 0, regen: 0, flash: 0, downed: false, revive: 0,
      shots: 0, trail: [], lastMove: { x: 0, y: -1 }, respawnShield: 0
    };
  }

  function createEnemy(type, x, y, wave, idle = false) {
    const def = DINO[type];
    const scale = idle ? 1 : 1 + (wave - 1) * (def.boss ? 0.2 : 0.135);
    const hp = Math.round(def.hp * scale);
    return {
      type, def, x, y, radius: def.radius, hp, maxHp: hp,
      speed: def.speed * (idle ? 1 : 1 + (wave - 1) * 0.012),
      damage: def.damage * (idle ? 1 : 1 + (wave - 1) * 0.06),
      angle: rand(0, TAU), anim: rand(0, TAU), walk: rand(0, 10), seed: rand(0, 100),
      flash: 0, attackCd: 0, dead: false, idle, boss: !!def.boss,
      chargeCd: 4.2 + rand(0, 2), charging: 0, hitStop: 0, targetId: -1,
      bossPhase: Math.random() * TAU, lunge: 0
    };
  }

  function startGame() {
    audio.init();
    audio.play('click');
    state.mode = 'playing';
    state.time = 0;
    state.score = 0;
    state.wave = 0;
    state.enemies = []; state.bullets = []; state.particles = []; state.pickups = [];
    state.texts = []; state.rings = []; state.spawnQueue = []; state.spawnTimer = 0;
    state.intermission = false; state.interTimer = 0; state.gameOverDelay = 0;
    state.shake = 0; state.hurtFlash = 0; state.levelFlash = 0; state.dino = null;
    state.kills = 0; state.hintTimer = 9; state.introTimer = 0;
    state.players = [createPlayer(0, 586, 638), createPlayer(1, 704, 638)];
    state.camera.x = D.W / 2; state.camera.y = D.H / 2;
    D.cameraLocked = false;
    ui.menu.classList.add('is-hidden');
    ui.gameover.classList.add('is-hidden');
    ui.pause.classList.add('is-hidden');
    ui.hud.classList.remove('is-hidden');
    ui.toast.innerHTML = '';
    ui.hint.classList.remove('fade');
    document.body.classList.remove('is-muted');
    document.body.classList.add('is-playing');
    state.players.forEach(p => { p.aim = -Math.PI / 2; p.angle = -Math.PI / 2; });
    startWave(1);
    updateHUD();
  }

  function showMenu() {
    state.mode = 'menu';
    state.enemies = []; state.bullets = []; state.particles = []; state.pickups = [];
    state.texts = []; state.rings = []; state.spawnQueue = [];
    state.players = [createPlayer(0, 488, 606), createPlayer(1, 660, 622)];
    state.players[0].angle = -0.7; state.players[0].aim = -0.7;
    state.players[1].angle = -2.2; state.players[1].aim = -2.2;
    state.enemies = [
      createEnemy('raptor', 956, 346, 1, true),
      createEnemy('raptor', 1046, 554, 2, true),
      createEnemy('stego', 1110, 402, 2, true),
      createEnemy('ptero', 854, 206, 2, true)
    ];
    state.enemies[0].angle = 2.6;
    state.enemies[1].angle = 2.9;
    state.enemies[2].angle = 2.45;
    state.enemies[3].angle = 3.4;
    state.time = 0;
    state.shake = 0; state.hurtFlash = 0; state.levelFlash = 0;
    state.camera.x = D.W / 2; state.camera.y = D.H / 2;
    ui.hud.classList.add('is-hidden');
    ui.menu.classList.remove('is-hidden');
    ui.gameover.classList.add('is-hidden');
    ui.pause.classList.add('is-hidden');
    ui.toast.innerHTML = '';
    ui.best.textContent = fmt(state.best || Number(localStorage.getItem('dinoduo.best') || 0));
    document.body.classList.remove('is-playing');
    updateHUD();
  }

  function startWave(n) {
    state.wave = n;
    state.intermission = false;
    state.spawnTimer = 0;
    state.spawnQueue = buildWave(n);
    const boss = n % 4 === 0;
    showBanner(`WAVE ${n}`, boss ? 'A titan stirs' : waveTagline(n), boss ? 'Its footsteps shake the island.' : 'The herd found your camp.');
    audio.play(boss ? 'roar' : 'wave');
    if (boss) state.shake = Math.max(state.shake, 8);
  }

  function waveTagline(n) {
    return ['Keep moving', 'They travel in packs', 'Hold the clearing', 'Watch the trees', 'No sign of rescue', 'The herd grows bold', 'Stand together'][Math.min(6, Math.max(0, n - 1))];
  }

  function buildWave(n) {
    const list = [];
    const raptors = Math.min(2 + Math.ceil(n * 1.15), 9);
    const pteros = n >= 2 ? Math.min(1 + Math.floor(n / 2), 5) : 0;
    const stegos = n >= 3 ? Math.min(1 + Math.floor((n - 3) / 2), 4) : 0;
    if (n % 4 === 0) list.push('rex');
    for (let i = 0; i < raptors; i++) list.push('raptor');
    for (let i = 0; i < pteros; i++) list.push('ptero');
    for (let i = 0; i < stegos; i++) list.push('stego');
    return list.map((type, i) => ({ type, at: 0.2 + i * (type === 'rex' ? 1.3 : 0.52) })).sort((a, b) => a.at - b.at);
  }

  function findSpawn(type, radius) {
    const boss = type === 'rex';
    for (let attempt = 0; attempt < 60; attempt++) {
      let x, y;
      if (boss) { x = 640 + rand(-160, 160); y = 120; }
      else {
        const side = Math.floor(rand(0, 4));
        if (side === 0) { x = rand(90, D.W - 90); y = rand(82, 180); }
        else if (side === 1) { x = rand(D.W - 160, D.W - 82); y = rand(120, D.H - 100); }
        else if (side === 2) { x = rand(90, D.W - 90); y = rand(D.H - 150, D.H - 85); }
        else { x = rand(82, 160); y = rand(120, D.H - 100); }
      }
      if (state.players.some(p => !p.downed && Math.hypot(p.x - x, p.y - y) < 250)) continue;
      let blocked = false;
      for (const t of world.trees) {
        if (Math.hypot(t.x - x, t.y - y) < t.r + radius + 24) { blocked = true; break; }
      }
      if (!blocked) return { x, y };
    }
    return { x: 640, y: 160 };
  }

  function spawnEnemy(type) {
    const spawn = findSpawn(type, DINO[type].radius);
    const e = createEnemy(type, spawn.x, spawn.y, state.wave);
    if (e.boss) {
      state.dino = e;
      state.shake = 20;
      showBanner('TITAN', 'The earth splits', 'Break line of sight. Keep firing.');
      audio.play('roar');
    }
    state.enemies.push(e);
    spawnRing(spawn.x, spawn.y, e.boss ? 92 : 48, e.boss ? '255,96,68' : '196,236,165');
    for (let i = 0; i < (e.boss ? 28 : 10); i++) {
      const a = rand(0, TAU), s = rand(30, e.boss ? 160 : 70);
      addParticle(spawn.x, spawn.y, Math.cos(a) * s, Math.sin(a) * s, e.boss ? '#ff9f74' : '#b8d59d', rand(0.3, 0.7), rand(1, 3));
    }
    return e;
  }

  /* ---------------- Update ---------------- */
  function update(dt) {
    state.time += dt;
    if (state.mode === 'menu') {
      updateParticles(dt);
      updateRings(dt);
      updateAmbient(dt);
      D.updateCamera(dt);
      return;
    }
    updateParticles(dt);
    updateRings(dt);
    updateTexts(dt);
    updateAmbient(dt);
    state.shake = Math.max(0, state.shake - dt * 30);
    state.hurtFlash = Math.max(0, state.hurtFlash - dt * 2.4);
    state.levelFlash = Math.max(0, state.levelFlash - dt * 2.4);
    if (state.mode === 'playing') {
      updateGame(dt);
      updatePickups(dt);
    }
    if (state.mode === 'playing' || state.mode === 'paused') updateHUD();
    D.updateCamera(dt);
    updateHint(dt);
    if (state.mode === 'paused' && input.pressed.size) input.pressed.clear();
    input.pressed.clear();
    input.dash[0] = false; input.dash[1] = false;
  }

  function updateHint(dt) {
    if (state.hintTimer == null) return;
    state.hintTimer -= dt;
    if (state.hintTimer <= 0) ui.hint.classList.add('fade');
  }

  function updateGame(dt) {
    for (const p of state.players) updatePlayer(p, dt);
    for (const e of state.enemies) updateEnemy(e, dt);
    updateBullets(dt);
    state.enemies = state.enemies.filter(e => !e.dead);

    if (state.spawnQueue.length) {
      state.spawnTimer += dt;
      while (state.spawnQueue.length && state.spawnQueue[0].at <= state.spawnTimer) {
        spawnEnemy(state.spawnQueue.shift().type);
      }
    }

    const anyDown = state.players.every(p => p.downed);
    if (anyDown) {
      if (state.gameOverDelay <= 0) {
        state.gameOverDelay = 1.15;
        showBanner('THE HERD WINS', 'Both rangers are down', 'The island keeps its secrets.');
        audio.play('gameover');
      } else {
        state.gameOverDelay -= dt;
        if (state.gameOverDelay <= 0) endGame();
      }
      return;
    }

    if (!state.intermission && !state.spawnQueue.length && !state.enemies.length) {
      state.intermission = true;
      state.interTimer = 3.8;
      state.score += state.wave * 100;
      for (const p of state.players) {
        if (!p.downed) p.hp = Math.min(p.maxHp, p.hp + p.maxHp * 0.08);
      }
      showBanner('HERD CLEARED', `Wave ${state.wave} survived`, `+${state.wave * 100} score · next wave incoming`);
      audio.play('wave');
    }

    if (state.intermission) {
      state.interTimer -= dt;
      if (state.interTimer <= 0) startWave(state.wave + 1);
    }
  }

  function updatePlayer(p, dt) {
    p.fireCd -= dt;
    p.dashCd = Math.max(0, p.dashCd - dt);
    p.dashTime = Math.max(0, p.dashTime - dt);
    p.invuln = Math.max(0, p.invuln - dt);
    p.flash = Math.max(0, p.flash - dt);
    p.walk += dt * (p.moving ? 10 : 2.4);

    if (p.downed) {
      p.revive = Math.max(0, p.revive - dt * 0.32);
      const mate = state.players.find(o => o !== p && !o.downed);
      if (mate && dist(p, mate) < 74) {
        p.revive += dt;
        if (Math.random() < dt * 14) {
          addParticle(p.x + rand(-12, 12), p.y + rand(-12, 12), rand(-8, 8), rand(-28, -10), '#ffd489', .6, rand(1, 2.4));
        }
        if (p.revive >= 2.05) revivePlayer(p);
      }
      return;
    }

    p.regen > 0 && (p.hp = Math.min(p.maxHp, p.hp + p.regen * dt));

    let mx = 0, my = 0;
    if (p.index === 0) {
      if (input.down('KeyA')) mx -= 1;
      if (input.down('KeyD')) mx += 1;
      if (input.down('KeyW')) my -= 1;
      if (input.down('KeyS')) my += 1;
    } else {
      if (input.down('ArrowLeft')) mx -= 1;
      if (input.down('ArrowRight')) mx += 1;
      if (input.down('ArrowUp')) my -= 1;
      if (input.down('ArrowDown')) my += 1;
    }
    const touch = input.touch[p.index];
    if (Math.hypot(touch.x, touch.y) > 0.08) {
      mx = touch.x; my = touch.y;
    }
    const mag = Math.hypot(mx, my);
    if (mag > 1) { mx /= mag; my /= mag; }
    p.moving = Math.hypot(mx, my) > 0.12;
    p.moveX = mx; p.moveY = my;
    if (p.moving) p.lastMove = norm(mx, my);

    const dashKey = p.index === 0 ? 'Space' : 'Enter';
    const wantsDash = input.pressed.has(dashKey) || (p.index === 1 && input.pressed.has('NumpadEnter')) || input.dash[p.index];
    if (wantsDash && p.dashCd <= 0 && p.dashTime <= 0) {
      let dx = mx, dy = my;
      if (Math.hypot(dx, dy) < 0.2) { dx = p.lastMove.x; dy = p.lastMove.y; }
      const nd = norm(dx, dy);
      p.dashVX = nd.x * 700; p.dashVY = nd.y * 700;
      p.dashTime = 0.17; p.dashCd = p.dashCdMax; p.invuln = Math.max(p.invuln, 0.28);
      spawnRing(p.x, p.y, 26, p.index ? '255,179,95' : '120,240,180');
      audio.play('dash');
    }

    let vx = mx * p.speed, vy = my * p.speed;
    if (p.dashTime > 0) { vx = p.dashVX; vy = p.dashVY; }
    if (Math.abs(vx) + Math.abs(vy) > 1) {
      const oldX = p.x, oldY = p.y;
      moveWithCollision(p, vx * dt, vy * dt, p.radius);
      if (p.dashTime > 0 && Math.random() < dt * 40) {
        addParticle(lerp(oldX, p.x, Math.random()), lerp(oldY, p.y, Math.random()), rand(-8, 8), rand(-8, 8), p.index ? '#ffb35f' : '#78f0b4', .28, rand(1, 2.4));
      }
    }

    const target = nearestEnemy(p, 560);
    if (target) {
      const lead = 0.04 + dist(p, target) / 2600;
      const tx = target.x + Math.cos(target.angle) * target.speed * lead * (target.idle ? 0 : 1);
      const ty = target.y + Math.sin(target.angle) * target.speed * lead * (target.idle ? 0 : 1);
      const desired = Math.atan2(ty - p.y, tx - p.x);
      p.aim += angleDelta(p.aim, desired) * Math.min(1, dt * 12);
      if (p.fireCd <= 0) fireAt(p, target);
    } else if (p.moving) {
      p.aim += angleDelta(p.aim, Math.atan2(my, mx)) * Math.min(1, dt * 6);
    }
    p.angle = p.aim;

    if (p.hp <= 0) downPlayer(p);
  }

  function nearestEnemy(p, range) {
    let best = null, bestD = range;
    for (const e of state.enemies) {
      if (e.dead) continue;
      const d = dist(p, e) - e.radius;
      if (d < bestD) { bestD = d; best = e; }
    }
    return best;
  }

  function fireAt(p, target) {
    p.fireCd = p.fireDelay;
    p.shots++;
    p.fireAngle = Math.atan2(target.y - p.y, target.x - p.x);
    const count = p.multiShot;
    const spread = 0.105;
    for (let i = 0; i < count; i++) {
      const offset = (i - (count - 1) / 2) * spread;
      const a = p.fireAngle + offset;
      const sx = p.x + Math.cos(a) * 22, sy = p.y + Math.sin(a) * 22;
      state.bullets.push({
        x: sx, y: sy, vx: Math.cos(a) * p.bulletSpeed, vy: Math.sin(a) * p.bulletSpeed,
        angle: a, speed: p.bulletSpeed, life: 1.45, damage: p.damage, owner: p.index,
        pierce: p.pierce, hit: new Set(), target: target, radius: 4,
        color: p.index ? '#ffc27a' : '#a8ffcf', trail: 0
      });
      addParticle(sx, sy, Math.cos(a) * 24, Math.sin(a) * 24, p.index ? '#ffd9a5' : '#d7ffe8', .16, rand(1, 2.2));
    }
    addParticle(p.x + Math.cos(p.fireAngle) * 24, p.y + Math.sin(p.fireAngle) * 24, 0, 0, p.index ? '#ffb35f' : '#78f0b4', .12, 5);
    audio.play('shoot');
  }

  function updateBullets(dt) {
    for (const b of state.bullets) {
      b.life -= dt;
      b.trail += dt;
      if (b.target && !b.target.dead) {
        const desired = Math.atan2(b.target.y - b.y, b.target.x - b.x);
        b.angle += clamp(angleDelta(b.angle, desired), -4.8 * dt, 4.8 * dt);
        b.vx = Math.cos(b.angle) * b.speed;
        b.vy = Math.sin(b.angle) * b.speed;
      }
      b.x += b.vx * dt; b.y += b.vy * dt;
      if (b.x < 0 || b.x > D.W || b.y < 0 || b.y > D.H) b.life = 0;
      if (b.life <= 0) continue;
      for (const e of state.enemies) {
        if (e.dead || b.hit.has(e)) continue;
        if (Math.hypot(b.x - e.x, b.y - e.y) < e.radius + b.radius + 2) {
          hitEnemy(e, b.damage, b.owner, b.x, b.y, b.angle);
          b.hit.add(e);
          if (b.pierce > 0) b.pierce--; else b.life = 0;
          break;
        }
      }
    }
    state.bullets = state.bullets.filter(b => b.life > 0);
  }

  function hitEnemy(e, damage, owner, x, y, angle) {
    e.hp -= damage;
    e.flash = 0.1;
    e.x += Math.cos(angle) * (e.boss ? 2 : 5);
    e.y += Math.sin(angle) * (e.boss ? 2 : 5);
    addText(x, y - e.radius * 0.6, String(Math.round(damage)), owner ? '#ffc98b' : '#bdffdd', 0.55);
    for (let i = 0; i < 5; i++) {
      const a = angle + Math.PI + rand(-1.2, 1.2);
      addParticle(x, y, Math.cos(a) * rand(20, 100), Math.sin(a) * rand(20, 100), i % 2 ? '#f2dfab' : '#8b4f33', rand(0.2, 0.5), rand(1, 2.7));
    }
    state.shake = Math.max(state.shake, e.boss ? 3 : 1.4);
    audio.play('hit');
    if (e.hp <= 0) killEnemy(e, owner);
  }

  function killEnemy(e, owner) {
    if (e.dead) return;
    e.dead = true;
    state.kills++;
    state.score += e.def.score;
    const pieces = e.boss ? 44 : 16;
    for (let i = 0; i < pieces; i++) {
      const a = rand(0, TAU), s = rand(20, e.boss ? 250 : 130);
      addParticle(e.x, e.y, Math.cos(a) * s, Math.sin(a) * s, i % 3 === 0 ? '#f4dd9d' : (e.boss ? '#b55036' : '#6a8b4d'), rand(0.35, 0.95), rand(1.2, e.boss ? 5 : 3.4));
    }
    spawnRing(e.x, e.y, e.boss ? 120 : 42, e.boss ? '255,126,86' : '236,218,160');
    state.shake = Math.max(state.shake, e.boss ? 18 : 4);
    addText(e.x, e.y - 28, `+${e.def.score}`, '#ffe7a3', 0.85);
    audio.play('kill');
    if (e.boss) {
      showBanner('TITAN DOWN', 'The island goes quiet', '+900 score');
      state.dino = null;
    }
    const orbCount = e.boss ? 6 : Math.min(3, 1 + Math.floor(e.def.xp / 9));
    for (let i = 0; i < orbCount; i++) {
      const a = rand(0, TAU), sp = rand(40, 130);
      state.pickups.push({
        type: 'xp', x: e.x, y: e.y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        value: Math.max(1, Math.round(e.def.xp / orbCount)), age: 0, life: 40, radius: 5,
        phase: rand(0, TAU), pull: false
      });
    }
    if (!e.boss && Math.random() < 0.075) {
      state.pickups.push({ type: 'berry', x: e.x, y: e.y, vx: rand(-30, 30), vy: rand(-30, 30), value: 22, age: 0, life: 40, radius: 8, phase: rand(0, TAU), pull: false });
    }
  }

  function updateEnemy(e, dt) {
    e.flash = Math.max(0, e.flash - dt);
    e.attackCd = Math.max(0, e.attackCd - dt);
    e.anim += dt;
    if (e.boss) {
      e.chargeCd -= dt;
      if (e.chargeCd <= 0 && e.charging <= 0) {
        e.charging = 0.85; e.chargeCd = 5.4 + rand(0, 1.2);
        spawnRing(e.x, e.y, 85, '255,88,64');
        state.shake = Math.max(state.shake, 12);
        audio.play('roar');
      }
      e.charging = Math.max(0, e.charging - dt);
    }
    const alive = state.players.filter(p => !p.downed);
    if (!alive.length) return;
    let target = alive[0], bestD = Infinity;
    for (const p of alive) { const d = dist(e, p); if (d < bestD) { bestD = d; target = p; } }
    e.targetId = target.index;
    let dx = target.x - e.x, dy = target.y - e.y;
    const d = Math.hypot(dx, dy) || 1;
    dx /= d; dy /= d;

    if (e.type === 'ptero') {
      const t = state.time * 2.2 + e.seed;
      const px = -dy, py = dx;
      dx += px * Math.sin(t) * 0.36;
      dy += py * Math.sin(t) * 0.36;
    } else if (e.type === 'raptor') {
      const px = -dy, py = dx;
      dx += px * Math.sin(state.time * 3.4 + e.seed) * 0.21;
      dy += py * Math.sin(state.time * 3.4 + e.seed) * 0.21;
    }

    let avoidX = 0, avoidY = 0;
    if (!e.fly) {
      for (const t of world.trees) {
        const ox = e.x - t.x, oy = e.y - t.y;
        const od = Math.hypot(ox, oy) || 1;
        const reach = t.r + e.radius + 48;
        if (od < reach) {
          const force = (reach - od) / reach;
          avoidX += ox / od * force * 1.7;
          avoidY += oy / od * force * 1.7;
        }
      }
    }
    for (const other of state.enemies) {
      if (other === e || other.dead) continue;
      const ox = e.x - other.x, oy = e.y - other.y;
      const od = Math.hypot(ox, oy) || 1;
      const reach = e.radius + other.radius + 14;
      if (od < reach) {
        const f = (reach - od) / reach;
        avoidX += ox / od * f * 0.8;
        avoidY += oy / od * f * 0.8;
      }
    }
    let ndx = dx + avoidX, ndy = dy + avoidY;
    const nm = Math.hypot(ndx, ndy) || 1;
    ndx /= nm; ndy /= nm;
    e.angle += angleDelta(e.angle, Math.atan2(ndy, ndx)) * Math.min(1, dt * 8);
    const speedMult = e.charging > 0 ? 2.7 : 1;
    const sp = e.speed * speedMult;
    moveWithCollision(e, ndx * sp * dt, ndy * sp * dt, e.radius, e.type === 'ptero');
    e.walk += dt * (2 + sp * 0.025);

    if (d < e.radius + target.radius + 4 && e.attackCd <= 0) {
      e.attackCd = e.boss ? 1.05 : 0.8;
      hurtPlayer(target, e.damage, e);
      const k = e.boss ? 34 : 18;
      moveWithCollision(target, (target.x - e.x) / d * k, (target.y - e.y) / d * k, target.radius);
    }
  }

  function hurtPlayer(p, amount, source) {
    if (p.invuln > 0 || p.downed) return;
    p.invuln = 0.82;
    p.flash = 0.18;
    p.hp -= amount;
    state.hurtFlash = Math.min(1, state.hurtFlash + 0.5);
    state.shake = Math.max(state.shake, source && source.boss ? 14 : 7);
    addText(p.x, p.y - 26, `-${Math.round(amount)}`, '#ff8f76', 0.65);
    spawnRing(p.x, p.y, 20, '255,93,76');
    for (let i = 0; i < 8; i++) {
      const a = rand(0, TAU);
      addParticle(p.x, p.y, Math.cos(a) * rand(20, 90), Math.sin(a) * rand(20, 90), '#ff8d74', rand(.22, .5), rand(1, 2.8));
    }
    audio.play('hurt');
    if (p.hp <= 0) downPlayer(p);
  }

  function downPlayer(p) {
    if (p.downed) return;
    p.downed = true;
    p.hp = 0;
    p.revive = 0;
    p.dashTime = 0;
    p.invuln = 2;
    state.shake = Math.max(state.shake, 12);
    spawnRing(p.x, p.y, 56, p.index ? '255,179,95' : '120,240,180');
    for (let i = 0; i < 18; i++) {
      const a = rand(0, TAU);
      addParticle(p.x, p.y, Math.cos(a) * rand(20, 120), Math.sin(a) * rand(20, 120), '#f0dcc0', rand(.3, .8), rand(1, 3));
    }
    const mate = state.players.find(o => o !== p);
    if (mate && !mate.downed) {
      showBanner(`${p.name} IS DOWN`, 'Get to your partner', 'Stand close for two seconds to revive.');
    }
  }

  function revivePlayer(p) {
    p.downed = false;
    p.hp = p.maxHp * 0.55;
    p.revive = 0;
    p.invuln = 1.7;
    p.respawnShield = 1.7;
    const mate = state.players.find(o => o !== p);
    if (mate && !mate.downed) {
      grantXp(mate, 16);
      mate.hp = Math.min(mate.maxHp, mate.hp + 12);
    }
    spawnRing(p.x, p.y, 60, p.index ? '255,179,95' : '120,240,180');
    addText(p.x, p.y - 34, 'BACK UP', p.index ? '#ffc27a' : '#a8ffcf', 1);
    showBanner(`${p.name} REVIVED`, 'Stay close', 'Shared health, shared fate.');
    audio.play('revive');
  }

  function grantXp(p, amount) {
    if (p.downed) return;
    p.xp += amount;
    addText(p.x, p.y - 19, `+${amount} XP`, 'rgba(255,227,160,.92)', 0.55);
    while (p.xp >= p.xpNext) {
      p.xp -= p.xpNext;
      p.level++;
      p.xpNext = Math.round(28 * Math.pow(p.level, 1.38));
      levelUp(p);
    }
  }

  function levelUp(p) {
    p.maxHp += 6;
    p.hp = Math.min(p.maxHp, p.hp + 18);
    p.damage += 1;
    let boon;
    if (p.level === 3) {
      p.multiShot = 2;
      boon = { name: 'Twin Darts', icon: '⋔', note: 'Your bow splits in two' };
    } else if (p.level === 5) {
      p.pierce = 1;
      boon = { name: 'Bone Piercer', icon: '➶', note: 'Darts punch through one dino' };
    } else if (p.level === 7) {
      p.multiShot = 3;
      boon = { name: 'Triple Flight', icon: '≡', note: 'Three darts per shot' };
    } else if (p.level === 9) {
      p.pierce = 2;
      boon = { name: 'Island Ballista', icon: '➹', note: 'Darts pierce even deeper' };
    } else {
      boon = D.BOONS[Math.floor(Math.random() * D.BOONS.length)];
      applyBoon(p, boon);
    }
    p.flash = 0.25;
    state.levelFlash = Math.min(1, state.levelFlash + 0.6);
    state.shake = Math.max(state.shake, 3);
    spawnRing(p.x, p.y, 64, p.index ? '255,192,110' : '170,255,207');
    for (let i = 0; i < 28; i++) {
      const a = rand(0, TAU), s = rand(30, 170);
      addParticle(p.x, p.y, Math.cos(a) * s, Math.sin(a) * s, i % 2 ? '#ffe3a0' : (p.index ? '#ffb35f' : '#78f0b4'), rand(.4, .9), rand(1, 3.8));
    }
    showLevelToast(p, boon);
    audio.play('level');
  }

  function applyBoon(p, boon) {
    if (boon.id === 'rapid') p.fireDelay = Math.max(0.18, p.fireDelay * 0.87);
    else if (boon.id === 'power') p.damage += 4;
    else if (boon.id === 'vitality') { p.maxHp += 20; p.hp = Math.min(p.maxHp, p.hp + 25); }
    else if (boon.id === 'fleet') p.speed *= 1.07;
    else if (boon.id === 'magnet') p.pickupRadius += 44;
    else if (boon.id === 'regen') { p.regen = Math.min(1.4, p.regen + 0.32); p.hp = Math.min(p.maxHp, p.hp + 20); }
  }

  function updatePickups(dt) {
    for (const orb of state.pickups) {
      orb.age += dt; orb.life -= dt;
      orb.phase += dt * 3;
      let nearest = null, nearD = Infinity;
      for (const p of state.players) {
        if (p.downed) continue;
        const d = dist(orb, p);
        if (d < nearD) { nearD = d; nearest = p; }
      }
      if (nearest && (nearD < nearest.pickupRadius || orb.pull)) {
        orb.pull = true;
        const n = norm(nearest.x - orb.x, nearest.y - orb.y);
        const accel = 480;
        orb.vx += n.x * accel * dt;
        orb.vy += n.y * accel * dt;
        orb.vx *= 0.96; orb.vy *= 0.96;
      } else {
        orb.vx *= 0.93; orb.vy *= 0.93;
      }
      orb.x += orb.vx * dt; orb.y += orb.vy * dt;
      orb.x = clamp(orb.x, 20, D.W - 20); orb.y = clamp(orb.y, 20, D.H - 20);
      if (nearest && nearD < nearest.radius + 15) {
        if (orb.type === 'xp') { grantXp(nearest, orb.value); orb.life = 0; audio.play('pickup'); }
        else {
          nearest.hp = Math.min(nearest.maxHp, nearest.hp + orb.value);
          addText(nearest.x, nearest.y - 30, `+${orb.value} HP`, '#a8ffcf', .7);
          spawnRing(nearest.x, nearest.y, 24, '160,255,190'); orb.life = 0; audio.play('pickup');
        }
        for (let i = 0; i < 6; i++) addParticle(orb.x, orb.y, rand(-40, 40), rand(-40, 40), orb.type === 'xp' ? '#ffd16a' : '#ff7b74', .3, rand(1, 2.2));
      }
    }
    state.pickups = state.pickups.filter(o => o.life > 0);
  }

  function moveWithCollision(e, dx, dy, radius, flying) {
    e.x = clamp(e.x + dx, PLAY.l + radius, PLAY.r - radius);
    e.y = clamp(e.y + dy, PLAY.t + radius, PLAY.b - radius);
    if (flying) return;
    for (const t of world.trees) {
      const ox = e.x - t.x, oy = e.y - t.y;
      const d = Math.hypot(ox, oy) || 0.001;
      const min = t.r + radius * 0.58;
      if (d < min) {
        e.x = t.x + ox / d * min;
        e.y = t.y + oy / d * min;
      }
    }
  }

  function endGame() {
    state.mode = 'gameover';
    state.gameOverDelay = 0;
    const best = Math.max(state.best || 0, state.score);
    state.best = best;
    try { localStorage.setItem('dinoduo.best', String(best)); } catch {}
    if (D.onGameOver) D.onGameOver();
  }

  /* ---------------- Effects ---------------- */
  function addParticle(x, y, vx, vy, color, life, size) {
    if (state.particles.length > 360) state.particles.shift();
    state.particles.push({ x, y, vx, vy, color, life, max: life, size, drag: rand(.88, .95), gravity: rand(0, 24) });
  }
  function spawnRing(x, y, r, rgb) {
    state.rings.push({ x, y, r, life: 0.5, max: 0.5, rgb });
  }
  function addText(x, y, text, color, life) {
    if (state.texts.length > 50) state.texts.shift();
    state.texts.push({ x, y, text, color, life, max: life, vy: -26 });
  }
  function updateParticles(dt) {
    for (const p of state.particles) {
      p.life -= dt;
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= Math.pow(p.drag, dt * 60); p.vy = p.vy * Math.pow(p.drag, dt * 60) + p.gravity * dt;
    }
    state.particles = state.particles.filter(p => p.life > 0);
  }
  function updateRings(dt) {
    for (const r of state.rings) r.life -= dt;
    state.rings = state.rings.filter(r => r.life > 0);
  }
  function updateTexts(dt) {
    for (const t of state.texts) { t.life -= dt; t.y += t.vy * dt; t.vy *= 0.96; }
    state.texts = state.texts.filter(t => t.life > 0);
  }

  /* ---------------- DOM / camera ---------------- */
  let lastLevel = [-1, -1];
  let lastDown = [false, false];
  function updateHUD() {
    for (let i = 0; i < 2; i++) {
      const p = state.players[i];
      if (!p) continue;
      const hp = clamp(p.hp / p.maxHp, 0, 1);
      ui.hp[i].style.width = `${hp * 100}%`;
      ui.hp[i].style.background = hp < .3 ? 'linear-gradient(90deg,#ff594d,#ff9f7a)' : '';
      ui.hpText[i].textContent = String(Math.max(0, Math.ceil(p.hp)));
      ui.xp[i].style.width = `${clamp(p.xp / p.xpNext, 0, 1) * 100}%`;
      if (lastLevel[i] !== p.level) { ui.levels[i].textContent = `LV ${p.level}`; lastLevel[i] = p.level; }
      if (lastDown[i] !== p.downed) { ui.cards[i].classList.toggle('downed', p.downed); lastDown[i] = p.downed; }
      const cooling = p.dashCd > 0.05;
      ui.dash[i].classList.toggle('cooling', cooling);
      D.ui.dashButtons[i].classList.toggle('cooling', cooling || p.downed);
    }
    ui.score.textContent = fmt(state.score);
    ui.wave.textContent = `WAVE ${Math.max(1, state.wave)}`;
    if (state.intermission) ui.waveSub.textContent = `NEXT WAVE IN ${Math.max(0, Math.ceil(state.interTimer))}s`;
    else if (state.spawnQueue.length) ui.waveSub.textContent = `${state.enemies.length + state.spawnQueue.length} DINOS INBOUND`;
    else ui.waveSub.textContent = state.enemies.length ? `${state.enemies.length} DINOS LEFT` : 'CLEAR THE HERD';
    const boss = state.enemies.find(e => e.boss && !e.dead);
    const showBoss = !!boss;
    ui.boss.classList.toggle('is-hidden', !showBoss);
    if (boss) ui.bossBar.style.width = `${clamp(boss.hp / boss.maxHp, 0, 1) * 100}%`;
  }

  function showBanner(kicker, title, small) {
    ui.bannerKick.textContent = kicker;
    ui.bannerTitle.textContent = title;
    ui.bannerSmall.textContent = small || '';
    ui.banner.classList.remove('show');
    void ui.banner.offsetWidth;
    ui.banner.classList.add('show');
  }

  function showLevelToast(p, boon) {
    const el = document.createElement('div');
    el.className = 'level-toast' + (p.index ? ' is-p2' : '');
    el.innerHTML = `<div class="lvl-badge">${p.level}</div><div class="lvl-copy"><b>${p.name} · LEVEL ${p.level}</b><span>${boon.name} — ${boon.note}</span></div><div class="lvl-icon">${boon.icon}</div>`;
    ui.toast.appendChild(el);
    while (ui.toast.children.length > 3) ui.toast.firstChild.remove();
    window.setTimeout(() => el.remove(), 3200);
  }

  function updateCamera(dt) {
    const w = D.view.w, h = D.view.h;
    if (!w || !h) return;
    const fixed = (w / h > 1.5) || (w >= 900 && w / h > 1.1);
    let targetZoom;
    if (fixed) targetZoom = Math.max(w / D.W, h / D.H) * 1.008;
    else targetZoom = Math.max(w / 620, h / 980);
    targetZoom = clamp(targetZoom, 0.55, 1.9);
    const cam = state.camera;
    cam.zoom = lerp(cam.zoom || targetZoom, targetZoom, Math.min(1, dt * 6));
    let tx = D.W / 2, ty = D.H / 2;
    if (!fixed && state.players && state.players.length) {
      const alive = state.players.filter(p => !p.downed);
      const list = alive.length ? alive : state.players;
      tx = list.reduce((s, p) => s + p.x, 0) / list.length;
      ty = list.reduce((s, p) => s + p.y, 0) / list.length;
    }
    const vw = w / cam.zoom, vh = h / cam.zoom;
    if (vw < D.W) tx = clamp(tx, vw / 2, D.W - vw / 2); else tx = D.W / 2;
    if (vh < D.H) ty = clamp(ty, vh / 2, D.H - vh / 2); else ty = D.H / 2;
    cam.x = lerp(cam.x, tx, Math.min(1, dt * 5));
    cam.y = lerp(cam.y, ty, Math.min(1, dt * 5));
  }

  D.createPlayer = createPlayer;
  D.createEnemy = createEnemy;
  D.startGame = startGame;
  D.showMenu = showMenu;
  D.startWave = startWave;
  D.update = update;
  D.updateCamera = updateCamera;
  D.updateHUD = updateHUD;
  D.updatePickups = updatePickups;
  D.moveWithCollision = moveWithCollision;
  D.grantXp = grantXp;
  D.levelUp = levelUp;
  D.hurtPlayer = hurtPlayer;
  D.spawnEnemy = spawnEnemy;
  D.DINO = DINO;
  D.showBanner = showBanner;
  D.updateEffects = (dt) => { updateParticles(dt); updateRings(dt); updateTexts(dt); };
})();

/* Dino Duo — all visuals are drawn procedurally on one canvas. */
(() => {
  'use strict';
  const D = window.DD;
  const { ctx, state, world } = D;
  const { clamp, lerp, TAU, dist } = D;
  const T = () => state.time;

  const SKINS = [
    { body: '#748f51', dark: '#49673a', belly: '#c5cf91', stripe: '#3d5830', eye: '#ffd166' },
    { body: '#a16b43', dark: '#6f452c', belly: '#d8b988', stripe: '#7a4b2e', eye: '#ffe08d' },
    { body: '#5f8579', dark: '#3b5d55', belly: '#b8ccb4', stripe: '#36554d', eye: '#ffd97a' }
  ];

  function shadow(x, y, rx, ry, alpha = 0.3, ox = 0, oy = 0) {
    ctx.save();
    ctx.translate(x + ox, y + oy);
    ctx.scale(1, ry / rx);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
    g.addColorStop(0, `rgba(0, 7, 4, ${alpha})`);
    g.addColorStop(0.65, `rgba(0, 7, 4, ${alpha * 0.55})`);
    g.addColorStop(1, 'rgba(0, 7, 4, 0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, rx, 0, TAU); ctx.fill();
    ctx.restore();
  }

  function ellipse(x, y, rx, ry, fill, rotation = 0) {
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, rotation, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
  }

  /* ---------------- Trees ---------------- */
  function drawTreeBases() {
    ctx.save();
    for (const t of world.trees) {
      const s = t.scale;
      shadow(t.x + 7 * s, t.y + 8 * s, 34 * s, 14 * s, 0.3);
      ctx.save();
      ctx.translate(t.x, t.y);
      const sway = Math.sin(T() * 0.55 + t.phase) * 2.2 * s;
      ctx.strokeStyle = '#46331e';
      ctx.lineCap = 'round';
      ctx.lineWidth = 7 * s;
      ctx.beginPath(); ctx.moveTo(0, 8 * s); ctx.quadraticCurveTo(2 * s, -8 * s, sway * 0.5, -26 * s); ctx.stroke();
      ctx.strokeStyle = 'rgba(155, 123, 70, .35)';
      ctx.lineWidth = 2.2 * s;
      ctx.beginPath(); ctx.moveTo(-1, 6 * s); ctx.quadraticCurveTo(0, -8 * s, sway * 0.5 - 1, -25 * s); ctx.stroke();
      // Exposed roots.
      ctx.strokeStyle = '#4a351f'; ctx.lineWidth = 2.4 * s;
      for (let i = -1; i <= 1; i += 2) {
        ctx.beginPath(); ctx.moveTo(0, 7 * s); ctx.quadraticCurveTo(i * 7 * s, 13 * s, i * 15 * s, 12 * s); ctx.stroke();
      }
      ctx.restore();
    }
    ctx.restore();
  }

  function treeAlpha(t) {
    let alpha = 1;
    for (const p of state.players) {
      if (!p || p.downed) continue;
      const d = Math.hypot(p.x - t.x, p.y - (t.y - 30 * t.scale));
      if (d < 76 * t.scale) alpha = Math.min(alpha, 0.3 + 0.45 * (d / (76 * t.scale)));
    }
    return alpha;
  }

  function drawTreeCanopies() {
    for (const t of world.trees) {
      const s = t.scale;
      const sway = Math.sin(T() * 0.55 + t.phase) * 3.2 * s;
      const cy = t.y - 49 * s;
      const alpha = treeAlpha(t);
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.translate(t.x + sway, cy);
      if (t.variant === 'palm') drawPalmCanopy(s, t.phase);
      else if (t.variant === 'fern') drawFernCanopy(s, t.phase);
      else drawBroadCanopy(s, t.phase);
      ctx.restore();
    }
  }

  function drawBroadCanopy(s, phase) {
    const greens = [['#1d4526', '#285c32', '#34713a', '#458144'], ['#244b27', '#2f6330', '#3d7839', '#528d4a'], ['#193e25', '#24552b', '#2f6936', '#468044']][Math.floor(phase) % 3];
    // Dark underside.
    ellipse(0, 12 * s, 50 * s, 40 * s, 'rgba(5, 18, 10, .34)', .12);
    const lobes = [
      [-31 * s, 4 * s, 27 * s], [29 * s, 5 * s, 25 * s], [-6 * s, -16 * s, 33 * s],
      [20 * s, -17 * s, 24 * s], [-25 * s, -12 * s, 23 * s], [2 * s, 8 * s, 30 * s]
    ];
    for (const [x, y, r] of lobes) {
      ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fillStyle = greens[1]; ctx.fill();
    }
    for (const [x, y, r] of lobes) {
      ctx.beginPath(); ctx.arc(x - 3 * s, y - 4 * s, r * .76, 0, TAU); ctx.fillStyle = greens[2]; ctx.fill();
    }
    for (let i = 0; i < 8; i++) {
      const a = phase + i * 2.4;
      const x = Math.cos(a) * 27 * s, y = Math.sin(a) * 16 * s - 4 * s;
      ctx.beginPath(); ctx.arc(x, y, (8 + (i % 3) * 3) * s, 0, TAU);
      ctx.fillStyle = i % 2 ? greens[3] : greens[2]; ctx.fill();
    }
    // Leaf flecks.
    for (let i = 0; i < 11; i++) {
      const a = phase * 2 + i * 2.1;
      const x = Math.cos(a) * (17 + (i % 3) * 9) * s;
      const y = Math.sin(a) * (12 + (i % 4) * 5) * s - 6 * s;
      ctx.beginPath(); ctx.arc(x, y, 2.2 * s, 0, TAU); ctx.fillStyle = 'rgba(125, 166, 91, .42)'; ctx.fill();
    }
    ctx.beginPath(); ctx.arc(-13 * s, -17 * s, 10 * s, 0, TAU); ctx.fillStyle = 'rgba(158, 190, 111, .13)'; ctx.fill();
  }

  function drawPalmCanopy(s, phase) {
    const count = 8;
    for (let i = 0; i < count; i++) {
      const a = i / count * TAU + Math.sin(T() * .8 + phase) * .035;
      const len = (42 + (i % 3) * 8) * s;
      ctx.save();
      ctx.rotate(a);
      ctx.strokeStyle = i % 2 ? '#4a8a48' : '#396f3b'; ctx.lineWidth = 3.4 * s; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(len * .5, -6 * s, len, 11 * s); ctx.stroke();
      ctx.fillStyle = i % 2 ? 'rgba(83, 145, 73, .7)' : 'rgba(61, 116, 58, .72)';
      for (let k = 0; k < 3; k++) {
        const t = .34 + k * .22;
        const x = len * t, y = -4 * s + t * t * 8 * s;
        ctx.beginPath(); ctx.ellipse(x, y, len * .105, 4.4 * s, .2, 0, TAU); ctx.fill();
      }
      ctx.restore();
    }
    for (let i = 0; i < 4; i++) {
      const a = phase + i * 1.8;
      ellipse(Math.cos(a) * 8 * s, Math.sin(a) * 5 * s, 4 * s, 3.5 * s, '#6a4824');
      ctx.beginPath(); ctx.arc(Math.cos(a) * 8 * s - 1 * s, Math.sin(a) * 5 * s - 1 * s, 1.2 * s, 0, TAU); ctx.fillStyle = '#9b733d'; ctx.fill();
    }
    ellipse(0, 3 * s, 13 * s, 10 * s, '#315b34', .2);
  }

  function drawFernCanopy(s, phase) {
    const count = 11;
    for (let i = 0; i < count; i++) {
      const a = i / count * TAU + phase * .2 + Math.sin(T() * .6 + phase) * .03;
      const len = (30 + (i % 4) * 5) * s;
      ctx.save(); ctx.rotate(a);
      ctx.strokeStyle = i % 2 ? '#4b7d3f' : '#326534';
      ctx.lineWidth = 2.4 * s; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(len * .5, 5 * s, len, -2 * s); ctx.stroke();
      for (let k = 1; k <= 3; k++) {
        const x = len * k / 4;
        ctx.beginPath(); ctx.ellipse(x, 2.5 * s, 6.2 * s, 2.5 * s, -.4, 0, TAU);
        ctx.fillStyle = i % 2 ? 'rgba(81, 133, 63, .76)' : 'rgba(58, 105, 50, .8)'; ctx.fill();
      }
      ctx.restore();
    }
    ellipse(0, 1 * s, 11 * s, 8 * s, '#2c5730');
  }

  /* ---------------- Players ---------------- */
  function drawPlayer(p) {
    if (!p) return;
    const def = p.def;
    const bob = p.moving ? Math.sin(p.walk) * 1.5 : Math.sin(T() * 2 + p.index) * .55;
    shadow(p.x, p.y + 9, 19, 9, .38);
    if (p.downed) { drawDownedPlayer(p); return; }
    ctx.save();
    ctx.translate(p.x, p.y + bob);
    ctx.rotate(p.angle);

    // Foot rings identify players at a glance.
    ctx.beginPath(); ctx.arc(0, 0, 20, 0, TAU);
    ctx.strokeStyle = `rgba(${def.glow}, ${p.dashCd > 0 ? .13 : .28})`;
    ctx.lineWidth = 1.2; ctx.setLineDash([3, 5]); ctx.stroke(); ctx.setLineDash([]);

    // Boots.
    const step = p.moving ? Math.sin(p.walk) * 5 : 0;
    ellipse(-7 + step, -7, 5.2, 3.2, '#1a2119', .1);
    ellipse(-7 - step, 7, 5.2, 3.2, '#1a2119', -.1);
    // Backpack.
    ctx.beginPath();
    ctx.roundRect(-15, -7, 10, 14, 3.5);
    ctx.fillStyle = def.dark; ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.14)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,.2)';
    ctx.fillRect(-13, -4, 2, 7);
    // Torso.
    ctx.beginPath(); ctx.ellipse(-1, 0, 11, 8.7, 0, 0, TAU);
    ctx.fillStyle = def.mid; ctx.fill();
    ctx.strokeStyle = 'rgba(5,20,13,.65)'; ctx.lineWidth = 1.6; ctx.stroke();
    // Vest / shoulder.
    ctx.beginPath(); ctx.ellipse(-1, -1, 7.5, 6, 0, 0, TAU);
    ctx.fillStyle = def.main; ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.23)'; ctx.lineWidth = 1; ctx.stroke();
    // Arms and crossbow.
    ctx.strokeStyle = '#2a2a20'; ctx.lineWidth = 3; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(2, 5); ctx.lineTo(12, 7); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(2, -5); ctx.lineTo(13, -3); ctx.stroke();
    ctx.fillStyle = '#332b20';
    ctx.save();
    ctx.translate(12, 5); ctx.rotate(-.06);
    ctx.fillRect(0, -1.8, 17, 3.6);
    ctx.strokeStyle = '#b7a77e'; ctx.lineWidth = 1.1;
    ctx.beginPath(); ctx.moveTo(15, 0); ctx.lineTo(25, 0); ctx.stroke();
    ctx.beginPath(); ctx.arc(3, 0, 4.4, -.9, .9); ctx.strokeStyle = def.main; ctx.lineWidth = 1.4; ctx.stroke();
    ctx.restore();
    // Head and hat.
    ctx.beginPath(); ctx.arc(5, 0, 6.2, 0, TAU);
    ctx.fillStyle = '#e3b387'; ctx.fill();
    ctx.strokeStyle = 'rgba(43,26,14,.55)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.beginPath(); ctx.ellipse(5, 0, 11.2, 8.2, 0, 0, TAU);
    ctx.fillStyle = def.dark; ctx.globalAlpha = .74; ctx.fill(); ctx.globalAlpha = 1;
    ctx.beginPath(); ctx.ellipse(5.5, 0, 6, 5.2, 0, 0, TAU);
    ctx.fillStyle = def.main; ctx.fill();
    ctx.beginPath(); ctx.ellipse(7, -3.1, 2.2, 1.6, 0, 0, TAU);
    ctx.fillStyle = 'rgba(247, 242, 210, .48)'; ctx.fill();
    // Tiny scarf trail.
    ctx.beginPath(); ctx.moveTo(-5, 0); ctx.quadraticCurveTo(-13, Math.sin(T() * 8 + p.index) * 3, -16, 1); ctx.strokeStyle = def.light; ctx.lineWidth = 1.5; ctx.stroke();
    // Cheek highlight.
    ctx.beginPath(); ctx.arc(7.2, 2.8, 1.1, 0, TAU); ctx.fillStyle = 'rgba(250, 210, 164, .8)'; ctx.fill();

    if (p.invuln > 0 && p.flash <= 0) {
      ctx.beginPath(); ctx.arc(0, 0, 22, 0, TAU); ctx.strokeStyle = `rgba(${def.glow}, .22)`; ctx.lineWidth = 1.5; ctx.stroke();
    }
    if (p.flash > 0) {
      ctx.globalAlpha = p.flash * 2.6;
      ctx.beginPath(); ctx.arc(0, 0, 15, 0, TAU); ctx.fillStyle = '#fff'; ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    // Level pips above the player.
    if (p.level > 1) {
      ctx.save();
      ctx.font = '900 8px "Trebuchet MS"'; ctx.textAlign = 'center';
      ctx.fillStyle = `rgba(${def.glow}, .85)`;
      ctx.fillText(`LV ${p.level}`, p.x, p.y - 25);
      ctx.restore();
    }
  }

  function drawDownedPlayer(p) {
    const def = p.def;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.angle + Math.PI / 2);
    ctx.globalAlpha = .8;
    ellipse(0, 0, 15, 8, '#1b2a20', .2);
    ctx.fillStyle = p.def.dark;
    ctx.beginPath(); ctx.roundRect(-12, -5, 22, 10, 5); ctx.fill();
    ctx.beginPath(); ctx.arc(10, 0, 5.5, 0, TAU); ctx.fillStyle = '#d8ab7c'; ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,.3)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.restore();
    // Revive ring.
    const r = p.revive / 2.05;
    ctx.beginPath(); ctx.arc(p.x, p.y, 22, 0, TAU); ctx.strokeStyle = 'rgba(6,18,11,.56)'; ctx.lineWidth = 4; ctx.stroke();
    if (r > 0) {
      ctx.beginPath(); ctx.arc(p.x, p.y, 22, -Math.PI / 2, -Math.PI / 2 + TAU * clamp(r, 0, 1));
      ctx.strokeStyle = '#ffd176'; ctx.lineWidth = 4; ctx.lineCap = 'round'; ctx.stroke();
    }
    ctx.font = '900 8px "Trebuchet MS"'; ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(255, 238, 190, .92)'; ctx.fillText(r > 0 ? 'REVIVING' : 'REVIVE', p.x, p.y - 30);
    ctx.beginPath(); ctx.arc(p.x, p.y - 39, 2 + Math.sin(T() * 6) * .5, 0, TAU); ctx.fillStyle = '#ffce7b'; ctx.fill();
  }

  /* ---------------- Dinosaurs ---------------- */
  function drawEnemy(e) {
    const skin = SKINS[Math.floor(e.seed) % SKINS.length];
    shadow(e.x, e.y + (e.type === 'ptero' ? 28 : e.radius * .54), e.radius * 1.45, e.radius * .55, .42);
    ctx.save();
    ctx.translate(e.x, e.y + (e.type === 'ptero' ? -7 + Math.sin(T() * 4 + e.seed) * 4 : 0));
    ctx.rotate(e.angle);
    if (e.charging > 0) {
      ctx.beginPath(); ctx.arc(0, 0, e.radius + 16 + Math.sin(T() * 18) * 3, 0, TAU);
      ctx.strokeStyle = 'rgba(255, 78, 55, .5)'; ctx.lineWidth = 3; ctx.stroke();
    }
    if (e.type === 'raptor') drawRaptor(e, skin);
    else if (e.type === 'ptero') drawPtero(e, skin);
    else if (e.type === 'stego') drawStego(e, skin);
    else drawRex(e, skin);
    if (e.flash > 0) {
      ctx.globalAlpha = Math.min(.8, e.flash * 7);
      ctx.beginPath(); ctx.ellipse(0, 0, e.radius * 1.35, e.radius * .8, 0, 0, TAU);
      ctx.fillStyle = '#fff7df'; ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();
    if (!e.boss && e.hp < e.maxHp) drawEnemyBar(e);
  }

  function drawRaptor(e, s) {
    const step = Math.sin(e.anim * 9 + e.seed) * 1;
    // Tail.
    ctx.beginPath();
    ctx.moveTo(-13, -2);
    ctx.quadraticCurveTo(-34, -8 + Math.sin(e.anim * 6) * 4, -54, 2 + Math.sin(e.anim * 6) * 6);
    ctx.quadraticCurveTo(-33, 3, -12, 6);
    ctx.closePath(); ctx.fillStyle = s.dark; ctx.fill();
    // Legs.
    ctx.strokeStyle = s.dark; ctx.lineWidth = 4.2; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-7, 5); ctx.lineTo(-4 + step * 5, 14); ctx.lineTo(2 + step * 5, 15); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(-9, -5); ctx.lineTo(-8 - step * 5, 12); ctx.lineTo(-2 - step * 5, 14); ctx.stroke();
    // Claws.
    ctx.strokeStyle = '#d8c9a0'; ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(2 + step * 5, 15); ctx.lineTo(6 + step * 5, 15); ctx.stroke();
    // Body.
    ctx.beginPath(); ctx.ellipse(-1, 0, 18, 9, -.05, 0, TAU);
    ctx.fillStyle = s.body; ctx.fill();
    ctx.strokeStyle = 'rgba(20,39,21,.5)'; ctx.lineWidth = 1.2; ctx.stroke();
    // Belly.
    ctx.beginPath(); ctx.ellipse(2, 3.2, 13, 4.2, -.08, 0, TAU); ctx.fillStyle = s.belly; ctx.globalAlpha = .75; ctx.fill(); ctx.globalAlpha = 1;
    // Stripes.
    ctx.strokeStyle = s.stripe; ctx.lineWidth = 1.6;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.moveTo(-9 + i * 7, -7); ctx.quadraticCurveTo(-6 + i * 7, 0, -9 + i * 7, 5); ctx.stroke();
    }
    // Neck and head.
    ctx.beginPath();
    ctx.moveTo(13, -5);
    ctx.quadraticCurveTo(20, -7, 27, -3);
    ctx.lineTo(35, -1);
    ctx.quadraticCurveTo(39, 1, 34, 4);
    ctx.lineTo(25, 5);
    ctx.quadraticCurveTo(19, 7, 14, 4);
    ctx.closePath(); ctx.fillStyle = s.body; ctx.fill();
    ctx.strokeStyle = 'rgba(20,39,21,.55)'; ctx.lineWidth = 1; ctx.stroke();
    // Jaw.
    ctx.beginPath(); ctx.moveTo(24, 3); ctx.quadraticCurveTo(31, 5, 36, 2); ctx.strokeStyle = s.dark; ctx.lineWidth = 2.2; ctx.stroke();
    // Teeth.
    ctx.strokeStyle = '#eee2bd'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(31, 2); ctx.lineTo(32, 4); ctx.moveTo(34, 2); ctx.lineTo(35, 3.5); ctx.stroke();
    // Eye.
    const blink = Math.sin(T() * 1.7 + e.seed) > .97 ? .25 : 1;
    ctx.save(); ctx.scale(1, blink);
    ctx.beginPath(); ctx.arc(29, -2.4, 1.9, 0, TAU); ctx.fillStyle = s.eye; ctx.fill();
    ctx.beginPath(); ctx.arc(29.5, -2.4, .85, 0, TAU); ctx.fillStyle = '#202517'; ctx.fill();
    ctx.restore();
    // Dorsal spikes.
    ctx.fillStyle = s.dark;
    for (let i = 0; i < 4; i++) {
      const x = -10 + i * 6;
      ctx.beginPath(); ctx.moveTo(x, -7); ctx.lineTo(x + 2.5, -11); ctx.lineTo(x + 4.5, -6.5); ctx.fill();
    }
  }

  function drawPtero(e, s) {
    const flap = Math.sin(e.anim * 11 + e.seed);
    // Wings.
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.scale(1, side);
      ctx.beginPath();
      ctx.moveTo(-4, -4);
      ctx.bezierCurveTo(-7, -22 - flap * 6, 16, -43 - flap * 9, 38, -30 - flap * 5);
      ctx.bezierCurveTo(25, -20, 15, -13, 9, -3);
      ctx.closePath();
      ctx.fillStyle = s.dark; ctx.fill();
      ctx.strokeStyle = 'rgba(11,32,21,.5)'; ctx.lineWidth = 1.2; ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-1, -5); ctx.bezierCurveTo(2, -18 - flap * 3, 18, -31 - flap * 5, 33, -26 - flap * 3);
      ctx.strokeStyle = 'rgba(214, 233, 175, .18)'; ctx.lineWidth = 1.1; ctx.stroke();
      ctx.restore();
    }
    // Tail.
    ctx.beginPath(); ctx.moveTo(-9, 0); ctx.quadraticCurveTo(-28, 4, -37, 0); ctx.quadraticCurveTo(-25, 7, -8, 5); ctx.fillStyle = s.dark; ctx.fill();
    // Body.
    ctx.beginPath(); ctx.ellipse(0, 0, 14, 6.2, 0, 0, TAU); ctx.fillStyle = s.body; ctx.fill();
    ctx.strokeStyle = 'rgba(14,35,25,.55)'; ctx.lineWidth = 1; ctx.stroke();
    // Neck + head.
    ctx.beginPath();
    ctx.moveTo(9, -4); ctx.quadraticCurveTo(18, -7, 24, -2); ctx.lineTo(34, -1);
    ctx.lineTo(30, 4); ctx.quadraticCurveTo(20, 5, 11, 4); ctx.closePath();
    ctx.fillStyle = s.body; ctx.fill();
    // Crest.
    ctx.beginPath(); ctx.moveTo(17, -5); ctx.lineTo(9, -15); ctx.lineTo(21, -7); ctx.fillStyle = s.stripe; ctx.fill();
    // Beak.
    ctx.beginPath(); ctx.moveTo(33, -1); ctx.lineTo(42, 1); ctx.lineTo(32, 3.5); ctx.fillStyle = '#d6b869'; ctx.fill();
    // Eye.
    ctx.beginPath(); ctx.arc(26, -2, 1.5, 0, TAU); ctx.fillStyle = s.eye; ctx.fill();
    // Feet.
    ctx.strokeStyle = s.dark; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(-4, 5); ctx.lineTo(-7, 11); ctx.moveTo(1, 5); ctx.lineTo(0, 11); ctx.stroke();
  }

  function drawStego(e, s) {
    const step = Math.sin(e.anim * 5 + e.seed) * .7;
    // Tail.
    ctx.beginPath();
    ctx.moveTo(-18, 0); ctx.quadraticCurveTo(-42, 4, -56, -9); ctx.quadraticCurveTo(-44, 10, -17, 8);
    ctx.fillStyle = s.dark; ctx.fill();
    // Tail spikes.
    ctx.fillStyle = '#d8c38b';
    ctx.beginPath(); ctx.moveTo(-50, -7); ctx.lineTo(-59, -15); ctx.lineTo(-47, -5); ctx.fill();
    ctx.beginPath(); ctx.moveTo(-52, 1); ctx.lineTo(-63, -2); ctx.lineTo(-49, 5); ctx.fill();
    // Legs.
    ctx.strokeStyle = s.dark; ctx.lineWidth = 6.5; ctx.lineCap = 'round';
    for (const side of [-1, 1]) {
      ctx.beginPath(); ctx.moveTo(-12 * side + 5, 9); ctx.lineTo(-12 * side + 6 + step * 3, 20); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-12 * side - 2, 9); ctx.lineTo(-11 * side - 2 - step * 3, 20); ctx.stroke();
    }
    // Body.
    ctx.beginPath(); ctx.ellipse(0, 0, 29, 16, -.03, 0, TAU); ctx.fillStyle = s.body; ctx.fill();
    ctx.strokeStyle = 'rgba(20,39,21,.5)'; ctx.lineWidth = 1.4; ctx.stroke();
    ctx.beginPath(); ctx.ellipse(5, 6, 20, 7, -.05, 0, TAU); ctx.fillStyle = s.belly; ctx.globalAlpha = .6; ctx.fill(); ctx.globalAlpha = 1;
    // Back plates.
    for (let i = 0; i < 5; i++) {
      const x = -19 + i * 9;
      const h = 10 + (i === 2 ? 6 : i === 1 || i === 3 ? 2 : 0);
      ctx.beginPath(); ctx.moveTo(x - 5, -10); ctx.lineTo(x, -10 - h); ctx.lineTo(x + 5, -9);
      ctx.fillStyle = i % 2 ? '#9d8e56' : '#b3a467'; ctx.fill();
      ctx.strokeStyle = 'rgba(47,44,26,.5)'; ctx.lineWidth = .8; ctx.stroke();
    }
    // Neck/head.
    ctx.beginPath();
    ctx.moveTo(22, -7); ctx.quadraticCurveTo(31, -12, 38, -7); ctx.lineTo(47, -3);
    ctx.quadraticCurveTo(42, 4, 34, 5); ctx.quadraticCurveTo(28, 6, 23, 7); ctx.fillStyle = s.body; ctx.fill();
    ctx.beginPath(); ctx.arc(41, -2, 1.6, 0, TAU); ctx.fillStyle = s.eye; ctx.fill();
    ctx.strokeStyle = s.dark; ctx.lineWidth = 1.6; ctx.beginPath(); ctx.moveTo(43, 2); ctx.lineTo(48, 2); ctx.stroke();
    // Small back stripes.
    ctx.strokeStyle = s.stripe; ctx.lineWidth = 1.2;
    for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.moveTo(-13 + i * 8, 6); ctx.lineTo(-11 + i * 8, 11); ctx.stroke(); }
  }

  function drawRex(e, s) {
    const step = Math.sin(e.anim * 5.4 + e.seed);
    const skin = { body: '#7f513a', dark: '#533325', belly: '#c8aa7f', stripe: '#49291e', eye: '#ffbb66' };
    // Tail.
    ctx.beginPath();
    ctx.moveTo(-31, -5); ctx.quadraticCurveTo(-75, 6, -98, -12); ctx.quadraticCurveTo(-70, 20, -30, 12);
    ctx.fillStyle = skin.dark; ctx.fill();
    // Legs.
    ctx.strokeStyle = skin.dark; ctx.lineWidth = 12; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-10, 8); ctx.lineTo(-8 + step * 6, 27); ctx.lineTo(2 + step * 6, 34); ctx.stroke();
