      } else {
        ctx.save();
        ctx.translate(a.x, a.y); ctx.rotate(a.rot);
        ctx.globalAlpha = .5;
        ctx.beginPath(); ctx.ellipse(0, 0, a.size * 1.5, a.size * .65, 0, 0, TAU);
        ctx.fillStyle = a.hue; ctx.fill();
        ctx.restore();
      }
    }
    ctx.restore();
  }

  /* ---------------- Scene ---------------- */
  function drawTerrain() {
    if (!world.terrain) return;
    ctx.drawImage(world.terrain, 0, 0);
    // Living water glints.
    const t = T();
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 5; i++) {
      const x = 1000 + Math.sin(t * .7 + i * 1.8) * 38 + i * 13;
      const y = 190 + Math.cos(t * .9 + i * 2.1) * 24 + (i % 3) * 12;
      ctx.globalAlpha = .07 + (i % 2) * .04;
      ctx.beginPath(); ctx.ellipse(x, y, 16 + i * 3, 1.5, -.2, 0, TAU); ctx.fillStyle = '#d6f3cf'; ctx.fill();
    }
    ctx.restore();
    // Boundary undergrowth.
    const g = ctx.createLinearGradient(0, 0, 0, 40);
    g.addColorStop(0, 'rgba(2,10,6,.66)'); g.addColorStop(1, 'rgba(2,10,6,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, D.W, 46);
    const g2 = ctx.createLinearGradient(0, D.H - 34, 0, D.H);
    g2.addColorStop(0, 'rgba(2,10,6,0)'); g2.addColorStop(1, 'rgba(2,10,6,.55)');
    ctx.fillStyle = g2; ctx.fillRect(0, D.H - 34, D.W, 34);
  }

  function drawWorld() {
    drawTerrain();
    drawTreeBases();
    drawPickups();
    const actors = [...state.players, ...state.enemies].sort((a, b) => a.y - b.y);
    for (const actor of actors) {
      if (actor.def && actor.maxHp && actor.hp === 0 && actor.downed === false) continue;
      if (actor.type) drawEnemy(actor); else drawPlayer(actor);
    }
    drawBullets();
    drawParticles();
    drawTreeCanopies();
    drawAmbient();
    drawRings();
    drawTexts();
  }

  function drawScreenFx() {
    const w = D.view.w, h = D.view.h;
    if (state.levelFlash > 0) {
      const g = ctx.createRadialGradient(w / 2, h / 2, 20, w / 2, h / 2, Math.max(w, h) * .72);
      g.addColorStop(0, `rgba(255, 216, 136, 0)`);
      g.addColorStop(.65, `rgba(255, 206, 108, ${state.levelFlash * .05})`);
      g.addColorStop(1, `rgba(255, 192, 80, ${state.levelFlash * .16})`);
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    }
    if (state.hurtFlash > 0) {
      const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * .22, w / 2, h / 2, Math.max(w, h) * .68);
      g.addColorStop(0, 'rgba(128, 8, 5, 0)');
      g.addColorStop(1, `rgba(154, 19, 9, ${state.hurtFlash * .34})`);
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    }
    const alive = state.players.filter(p => p && !p.downed);
    if (alive.length && state.mode === 'playing') {
      const lowest = Math.min(...alive.map(p => p.hp / p.maxHp));
      if (lowest < .32) {
        const pulse = .07 + (1 - lowest / .32) * .1 + Math.sin(T() * 4) * .025;
        const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * .2, w / 2, h / 2, Math.max(w, h) * .65);
        g.addColorStop(0, 'rgba(120,0,0,0)'); g.addColorStop(1, `rgba(145, 12, 6, ${pulse})`);
        ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
      }
    }
  }

  D.render = function () {
    const view = D.view;
    if (!view.w || !view.h) return;
    ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
    ctx.fillStyle = '#07160e';
    ctx.fillRect(0, 0, view.w, view.h);
    const cam = state.camera;
    const shake = state.shake;
    const sx = shake ? D.rand(-shake, shake) : 0;
    const sy = shake ? D.rand(-shake, shake) : 0;
    ctx.save();
    ctx.translate(view.w / 2 + sx, view.h / 2 + sy);
    ctx.scale(cam.zoom, cam.zoom);
    ctx.translate(-cam.x, -cam.y);
    drawWorld();
    ctx.restore();
    drawScreenFx();
  };
})();

/* Dino Duo — boot, UI wiring and the animation loop. */
(() => {
  'use strict';
  const D = window.DD;
  const { state, ui, input, audio } = D;

  function resize() {
    const w = Math.max(320, window.innerWidth);
    const h = Math.max(320, window.innerHeight);
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    D.view.w = w; D.view.h = h; D.view.dpr = dpr;
    D.canvas.width = Math.round(w * dpr);
    D.canvas.height = Math.round(h * dpr);
    D.canvas.style.width = w + 'px';
    D.canvas.style.height = h + 'px';
    if (state.mode === 'menu') {
      state.camera.x = D.W / 2; state.camera.y = D.H / 2;
    }
  }

  function togglePause() {
    if (state.mode === 'playing') {
      state.mode = 'paused';
      input.keys.clear();
      input.touch[0].x = input.touch[0].y = 0;
      input.touch[1].x = input.touch[1].y = 0;
      document.querySelectorAll('.joystick-knob').forEach(k => k.style.transform = '');
      ui.pause.classList.remove('is-hidden');
      audio.play('click');
    } else if (state.mode === 'paused') {
      state.mode = 'playing';
      ui.pause.classList.add('is-hidden');
      audio.init();
      audio.play('click');
    }
  }

  function toMenu() {
    state.mode = 'menu';
    ui.pause.classList.add('is-hidden');
    ui.gameover.classList.add('is-hidden');
    D.showMenu();
  }

  function start() {
    ui.gameover.classList.add('is-hidden');
    ui.pause.classList.add('is-hidden');
    D.startGame();
    audio.play('click');
  }

  function gameOver() {
    ui.resultWave.textContent = String(state.wave);
    ui.resultScore.textContent = D.fmt(state.score);
    ui.resultLevels[0].textContent = String(state.players[0] ? state.players[0].level : 1);
    ui.resultLevels[1].textContent = String(state.players[1] ? state.players[1].level : 1);
    ui.overCopy.textContent = state.wave >= 4
      ? 'You toppled a titan. The island remembers.'
      : state.wave >= 2
        ? 'You made a dent in the food chain.'
        : 'The herd was hungrier than you were.';
    ui.best.textContent = D.fmt(state.best);
    ui.gameover.classList.remove('is-hidden');
    input.keys.clear();
    ui.dashButtons.forEach(b => b.classList.remove('cooling'));
  }

  function bindEvents() {
    window.addEventListener('resize', resize);
    window.addEventListener('orientationchange', () => setTimeout(resize, 120));
    window.addEventListener('keydown', (e) => {
      const blocked = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'Enter'].includes(e.code);
      if (blocked && state.mode !== 'menu') e.preventDefault();
      if (e.repeat) return;
      audio.init();
      input.keys.add(e.code);
      input.pressed.add(e.code);
      if (e.code === 'KeyP' || e.code === 'Escape') {
        if (state.mode === 'playing' || state.mode === 'paused') togglePause();
      } else if (e.code === 'Enter' && state.mode === 'menu') {
        start();
      } else if ((e.code === 'Enter' || e.code === 'Space') && state.mode === 'gameover') {
        start();
      }
    });
    window.addEventListener('keyup', (e) => input.keys.delete(e.code));
    window.addEventListener('blur', () => {
      input.keys.clear();
      input.touch[0].x = input.touch[0].y = 0;
      input.touch[1].x = input.touch[1].y = 0;
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && state.mode === 'playing') togglePause();
    });

    ui.start.addEventListener('click', start);
    ui.again.addEventListener('click', start);
    ui.resume.addEventListener('click', togglePause);
    ui.quit.addEventListener('click', toMenu);
    ui.title.addEventListener('click', toMenu);
    ui.pauseBtn.addEventListener('click', togglePause);
    ui.sound.addEventListener('click', () => {
      audio.init();
      audio.setMuted(!audio.muted);
      ui.sound.setAttribute('aria-label', audio.muted ? 'Unmute sound' : 'Mute sound');
      if (!audio.muted) audio.play('click');
    });

    D.onGameOver = gameOver;
  }

  function boot() {
    D.buildWorld();
    D.setupTouch();
    bindEvents();
    resize();
    D.showMenu();
    ui.sound.setAttribute('aria-label', audio.muted ? 'Unmute sound' : 'Mute sound');
    ui.best.textContent = D.fmt(state.best);
    let last = performance.now();
    function frame(now) {
      const dt = Math.min(0.034, Math.max(0, (now - last) / 1000));
      last = now;
      D.update(dt);
      D.render();
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);

    // Small, read-only-ish harness for automated smoke checks.
    window.__dinoDuo = {
      snapshot: () => ({
        mode: state.mode, wave: state.wave, score: state.score,
        enemies: state.enemies.length, pickups: state.pickups.length,
        players: state.players.map(p => ({ name: p.name, x: Math.round(p.x), y: Math.round(p.y), hp: Math.round(p.hp), level: p.level, xp: p.xp, downed: p.downed, multiShot: p.multiShot }))
      }),
      start: start,
      pause: togglePause,
      grantXp: (index, amount) => { if (state.players[index]) D.grantXp(state.players[index], amount); },
      spawn: (type) => D.spawnEnemy(type),
      hurt: (index, amount) => { if (state.players[index]) D.hurtPlayer(state.players[index], amount, null); },
      startWave: (n) => D.startWave(n)
    };
  }

  boot();
})();

