    }
    for (let i = 0; i < 4; i++) {
      const a = index * .7 + i * 1.8;
      c.beginPath(); c.ellipse(Math.cos(a) * 8 * s, Math.sin(a) * 5 * s, 4 * s, 3.5 * s, 0, 0, TAU); c.fillStyle = '#6a4824'; c.fill();
