  }
}

/* ---------------- Players ---------------- */
function drawPlayer(p) {
  if (!p) return;
  const def = p.def;
  const bob = p.moving ? Math.sin(p.walk) * 1.5 : Math.sin(T() * 2 + p.index) * .55;
  shadow(p.x, p.y + 9, 19, 9, .38);
  if (p.downed) { drawDownedPlayer(p); return; }
