  ctx.translate(p.x, p.y + bob);
  ctx.rotate(p.angle);
  ctx.scale(1.42, 1.42);

  // Foot rings identify players at a glance.
  ctx.beginPath(); ctx.arc(0, 0, 21, 0, TAU);
